# Shared helpers for real-SSH E2E (docker-ssh workers).

if !isdefined(Main, :_ssh_e2e_enabled)

using Dates

"""True when CI / local docker-ssh E2E should run."""
function _ssh_e2e_enabled()::Bool
    return get(ENV, "DISTSSHKIT_SSH_E2E", "") == "1"
end

"""Path to `testenv/docker-ssh` (repo-relative)."""
function _docker_ssh_root()::String
    return abspath(joinpath(_kit_root(), "testenv", "docker-ssh"))
end

"""SSH config / hosts file generated by `scripts/gen-keys.sh`."""
function _docker_ssh_generated()
    root = _docker_ssh_root()
    return (
        ssh_config=joinpath(root, ".generated", "ssh_config"),
        hosts_file=joinpath(root, ".generated", "hosts"),
        controller_key=joinpath(root, ".generated", "controller"),
    )
end

"""ENV overlay so DistSSHKit uses the docker-ssh SSH config (`-F`)."""
function _ssh_e2e_env(;
    remote_project::AbstractString,
    extra::Dict{String,String}=Dict{String,String}(),
)::Dict{String,String}
    g = _docker_ssh_generated()
    isfile(g.ssh_config) || error("missing $(g.ssh_config); run testenv/docker-ssh/scripts/up.sh")
    base = Dict{String,String}(
        "DISTSSHKIT_YES" => "1",
        "DISTSSHKIT_QUIET" => get(ENV, "DISTSSHKIT_QUIET", "1"),
        "DISTRIBUTED_SSH_OPTS" => "-F $(g.ssh_config) -o RequestTTY=no",
        "DISTRIBUTED_REMOTE_PROJECT_ROOT" => String(remote_project),
        # setup --sync / git push use this; DistSSHKit's git_push_project! has no -F flag.
        "GIT_SSH_COMMAND" => "ssh -F $(g.ssh_config) -o RequestTTY=no",
    )
    return merge(base, extra)
end

"""`ssh -F docker-ssh config HOST REMOTE_CMD` (same RequestTTY policy as kit defaults).

Setup existence checks (`test -e` / `test -d`), git, rsync, and `pgrep` stay
here. Remote Julia work uses `_e2e_run_on_host`.
"""
function _ssh_e2e_ssh(host::AbstractString, remote_cmd::AbstractString)
    g = _docker_ssh_generated()
    return _run_subprocess(Cmd([
        "ssh", "-F", g.ssh_config, "-o", "RequestTTY=no",
        String(host), String(remote_cmd),
    ]))
end

"""Capture stdout of remote Julia via kit `ssh_opts` + `run_on_host` inner sh.

Call under `withenv` that sets `DISTRIBUTED_SSH_OPTS` (E2E `_ssh_e2e_env`).
"""
function _e2e_run_on_host(host::AbstractString, argv::AbstractVector{<:AbstractString})
    inner = DistSSHKit._run_on_host_remote_sh(String[String(a) for a in argv])
    return _run_subprocess(Cmd(vcat(["ssh"], DistSSHKit.ssh_opts(), [String(host), inner])))
end

_ssh_e2e_hosts() = ("distsshkit-w1", "distsshkit-w2")
_ssh_e2e_remote_root() = "/home/dev/distsshkit-e2e"

"""juliaup channels baked into the worker image (from `up.sh` / julia-slots.env)."""
function _ssh_e2e_julia_channels()::NamedTuple{(:default, :alt),Tuple{String,String}}
    def = strip(get(ENV, "DISTSSHKIT_E2E_JULIA_DEFAULT_CHANNEL", ""))
    alt = strip(get(ENV, "DISTSSHKIT_E2E_JULIA_ALT_CHANNEL", ""))
    isempty(def) && (def = DistSSHKit.juliaup_channel())
    isempty(alt) && throw(ArgumentError(
        "DISTSSHKIT_E2E_JULIA_ALT_CHANNEL unset; run testenv/docker-ssh/scripts/up.sh --e2e " *
        "(or apple-container-ssh) so slots min/max are exported",
    ))
    return (; default=String(def), alt=String(alt))
end

"""Set remote juliaup default channel (`\$HOME/.juliaup/bin/juliaup default …`)."""
function _ssh_e2e_juliaup_default!(host::AbstractString, channel::AbstractString)
    ch = String(channel)
    proc, out = _ssh_e2e_ssh(
        host,
        "\$HOME/.juliaup/bin/juliaup default $(Base.shell_escape(ch))",
    )
    proc.exitcode == 0 || error("juliaup default $ch on $host failed: $out")
    DistSSHKit.clear_detect_julia_path_cache!(String(host))
    return nothing
end

"""Local juliaup on the kit parent (required for `setup --juliaup parent` E2E)."""
function _ssh_e2e_local_juliaup()::String
    ju = DistSSHKit.find_local_juliaup()
    ju === nothing && error(
        "local juliaup not found; kit parent E2E needs \$HOME/.juliaup/bin/juliaup " *
        "or Homebrew juliaup",
    )
    return ju
end

"""`juliaup default` on the kit parent (`add` first if the channel is missing)."""
function _ssh_e2e_juliaup_default_local!(channel::AbstractString)
    ju = _ssh_e2e_local_juliaup()
    ch = String(channel)
    add = run(ignorestatus(Cmd([ju, "add", ch])); wait=true)
    if add.exitcode != 0
        st = try
            read(Cmd([ju, "status"]), String)
        catch
            ""
        end
        occursin(ch, st) || error("juliaup add $ch failed on kit parent")
    end
    run(Cmd([ju, "default", ch]); wait=true)
    return nothing
end

"""Version of the Julia shim beside the kit parent's juliaup."""
function _ssh_e2e_local_juliaup_julia_version()::VersionNumber
    ju = _ssh_e2e_local_juliaup()
    jl = DistSSHKit._local_julia_beside_juliaup(ju)
    isfile(jl) || error("Julia not found beside juliaup: $jl")
    ver = DistSSHKit.parse_julia_version(read(`$jl --version`, String))
    ver === nothing && error("unparseable julia --version from $jl")
    return ver
end
